-- Declared foreign keys for party module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('party.party_addresses') IS NOT NULL AND to_regclass('party.parties') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('party.party_addresses') AND c.contype = 'f' AND a.attname = 'party_id'
    ) THEN
        ALTER TABLE party.party_addresses ADD CONSTRAINT fk_party_addresses_party_id FOREIGN KEY (party_id) REFERENCES party.parties (id) NOT VALID;
        BEGIN
            ALTER TABLE party.party_addresses VALIDATE CONSTRAINT fk_party_addresses_party_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_party_addresses_party_id left NOT VALID: stored rows of party.party_addresses reference missing rows';
        END;
    END IF;
END $$;

